<template>
  <div class="echarts">
    <div
      class="echartWrap"
      :id="echartId"
      :style="{
        width:
          echartWidth.toString().indexOf('calc') == -1
            ? echartWidth + 'px'
            : echartWidth,
        height:
          echartHeight.toString().indexOf('calc') == -1
            ? echartHeight + 'px'
            : echartHeight,
      }"
    ></div>
  </div>
</template>

<script>
export default {
  name: "echarts",
  props: ["echartId", "echartWidth", "echartHeight", "echartOptions"],
  data() {
    return {
      myChart: null,
    };
  },
  watch: {
    echartOptions() {
      setTimeout(() => {
        this.myChart && this.myChart.setOption(this.$props.echartOptions, true);
      }, 300);
    },
  },
  mounted() {
    this.drawLine();
    if (
      this.echartWidth.toString().indexOf("calc") != -1 ||
      this.echartHeight.toString().indexOf("calc") != -1
    ) {
      let timeout;
      window.addEventListener("resize", () => {
        clearTimeout(timeout);
        timeout = setTimeout(() => {
          this.myChart && this.myChart.resize();
        }, 200);
      });
    }
  },
  methods: {
    drawLine() {
      //基于准备好的dom，初始化echarts实例
      let that = this;
      let myChart = this.$echarts.init(
        document.getElementById(this.$props.echartId)
      );
      this.myChart = myChart;
      //绘制图表
      myChart.setOption(this.$props.echartOptions);
      myChart.on("finished", function () {
        if (that.$listeners["finished"]) {
          that.$emit("finished");
        }
      });
    },
    getEchart() {
      return this.myChart;
    }
  },
};
</script>

<style lang="scss" scoped>
.echarts{
  height: 100%;
}
.echartWrap {
  box-sizing: border-box;
  margin: 0 auto;
}
</style>