import axios from 'axios';
import { Message } from 'element-ui';

import router from '../router/index.js';
import store from '../store/index.js';

let goLogin = false;

axios.defaults.withCredentials = true;
let service = axios.create({
    baseURL: 'http://127.0.0.1:25125/api/',
    timeout: 60000,
    isLoading: true
});


// 请求拦截 可在请求头中加入token等
service.interceptors.request.use(
    config => {
        if (config.url.indexOf('?') >= 0) {
            config.url += '&_t=' + new Date().getTime();
        } else {
            config.url += '?_t=' + new Date().getTime();
        }

        let token = store.state.User.userInfo.token;
        if (token) {
            config.headers['Authorization'] = 'Bearer ' + token;
        }

        return config;
    },
    error => {
        return Promise.reject(error);
    }
);

// 响应拦截 对响应消息作初步的处理
service.interceptors.response.use(
    resp => {
        let data = resp.data;

        if (data.code == 403) {
            try {
                if (!goLogin) {
                    goLogin = true;
                    Message.error({
                        message: '用户登陆信息已失效，请重新登陆'
                    });
                    store.commit('User/USER_INFO', {});
                    localStorage.removeItem('vuex');

                    router.push('/login');
                    setTimeout(() => {
                        goLogin = false
                    }, 500)
                }
            } catch (error) { }
        } else if (data.code != 200 && data.code != 1000 && data.code != undefined) {
            try {
                Message.error({
                    message: data.msg
                });
            } catch (error) { }
        }

        return data;
    },
    err => {

        let errStr = ''
        if (err.message !== '取消请求') {
            if (err && err.response) {
                switch (err.response.code) {
                    case 400:
                        errStr = '错误请求';
                        break;
                    case 401:
                        errStr = '登录信息失效';
                        break;
                    case 403:
                        errStr = '拒绝访问';
                        break;
                    case 404:
                        errStr = '请求错误,未找到该资源';
                        break;
                    case 405:
                        errStr = '请求方法未允许';
                        break;
                    case 408:
                        errStr = '请求超时';
                        break;
                    case 500:
                        errStr = '服务器端出错';
                        break;
                    case 501:
                        errStr = '网络未实现';
                        break;
                    case 502:
                        errStr = '网络错误';
                        break;
                    case 503:
                        errStr = '服务不可用';
                        break;
                    case 504:
                        errStr = '网络超时';
                        break;
                    case 505:
                        errStr = 'http版本不支持该请求';
                        break;
                    default:
                        errStr = `连接错误${err.response.code}`;
                }
            } else {
                errStr = '网络异常，请稍后再试...';
            }
            Message.error({ message: errStr });
        }

        return err;
    }
);

export default service;
