<template>
  <div class="login-wrap">
    <div class="titleBox">
      <img src="../assets/img/logo.png" />
      <span>“慧眼”村镇银行全风险智能监测平台登录页</span>
    </div>

    <div class="ms-login">
      <!-- 登陆 -->
      <el-form
        :model="param"
        :rules="rules"
        ref="loginForm"
        label-width="0px"
        class="ms-content"
      >
        <el-form-item prop="userid">
          <el-input
            v-model.trim="param.userid"
            oninput="value=value.replace(/[\u4E00-\u9FA5]/g,'')"
            placeholder="请输入工号/账号"
            clearable
          ></el-input>
        </el-form-item>
        <el-form-item prop="password lastItem">
          <el-input
            type="passWord"
            placeholder="请输入密码"
            v-model.trim="param.password"
            oninput="value=value.replace(/[\u4E00-\u9FA5]/g,'')"
            @keyup.enter.native="submitForm()"
            show-password
          ></el-input>
        </el-form-item>
        <div class="forgetPassword">
          <el-checkbox v-model="checked" @change="changeCheck"
            >记住账号</el-checkbox
          >
        </div>
        <div class="login-btn">
          <el-button
            type="primary"
            @click="submitForm()"
            :loading="loginLoading"
            >登录</el-button
          >
        </div>
      </el-form>
    </div>
  </div>
</template>

<script>
import { getLogin } from "../api/home";

export default {
  data() {
    return {
      loginLoading: false,
      checked: true,

      param: {
        userid: "",
        password: "",
      },
      rules: {
        userid: [
          {
            required: true,
            message: "请输入账号",
            trigger: "blur",
          },
        ],
        password: [
          {
            required: true,
            message: "请输入密码",
            trigger: "blur",
          },
        ],
      },
    };
  },
  created() {
    this.checked = localStorage.getItem("checked") == "true";
    if (this.checked) {
      this.param.userid = localStorage.getItem("userid") || "";
    }
  },
  methods: {
    changeCheck(val) {
      if (val) {
        localStorage.setItem("checked", true);
      } else {
        localStorage.removeItem("checked");
        localStorage.removeItem("userid");
      }
    },
    async goLogin() {
      this.loginLoading = true;
      let res = await getLogin({
        ...this.param,
        password: this.$md5.hash(this.param.password),
      });
      this.loginLoading = false;

      if (res.code == 200) {
        if (this.checked) {
          localStorage.setItem("userid", this.param.userid);
        }

        this.$message.success("登录成功");

        this.$store.commit("User/USER_INFO", {
            ...res.user,
            token: res.token
        });

        this.$router.push("/");
      }
    },

    // 登录按钮
    submitForm() {
      this.$refs.loginForm.validate(async (valid) => {
        if (valid) {
          this.goLogin();
        }
      });
    },
  },
};
</script>

<style lang="scss" scoped>
