<template>
  <div class="homeWrap">
    <div class="topBox">
      <div class="leftBox">
        <div class="text">{{ dateStr }}</div>
        <div class="text">{{ dateWeek }}</div>
        <div class="time">{{ dateTime }}</div>
      </div>
      <div class="settingWrap">
        <div class="btn" @click="settingFn()" v-if="showImport">模型配置</div>

        <div class="btn" @click="batchFn()" v-if="showImport">数据管理</div>

        <el-upload
          accept=".xlsx, .xls"
          multiple
          :limit="20"
          :show-file-list="false"
          :auto-upload="false"
          :file-list="fileList"
          :on-change="httpRequest"
          :on-exceed="handleExceed"
          action=""
        >
          <el-button class="btn" v-if="showImport" :loading="uploadLoading"
            >点击上传</el-button
          >
        </el-upload>

        <div class="settingBox" v-if="showImport">
          <div class="imgBtn" @click="showSettingFn"></div>

          <transition name="el-fade-in-linear">
            <div class="selectBox" v-show="showSetting">
              <div class="selectBtn" @click="clickSettingFn(1)">
                <img src="../assets/img/icon2.png" />
                <span>部门管理</span>
              </div>
              <div class="selectBtn" @click="clickSettingFn(2)">
                <img src="../assets/img/icon3.png" />
                <span>人员管理</span>
              </div>
            </div>
          </transition>
        </div>
      </div>
    </div>
    <div class="rightBox">
      <div
        class="btn"
        :class="{ active: tabIndex == 1 }"
        @click="changeTab(1)"
        :style="{
          'z-index':
            dialogShow || dialogLoading1 || modelDialog ? '30' : '3000',
        }"
      >
        模型监控
      </div>
      <div
        class="btn"
        :class="{ active: tabIndex == 2 }"
        @click="changeTab(2)"
        :style="{
          'z-index':
            dialogShow || dialogLoading1 || modelDialog ? '30' : '3000',
        }"
      >
        趋势概览
      </div>
      <div
        class="timeBox"
        :style="{
          'z-index':
            dialogShow || dialogLoading1 || modelDialog ? '30' : '3000',
        }"
      >
        <!-- <el-date-picker
          v-show="tabIndex == 1"
          v-model="dataTime"
          type="month"
          :clearable="false"
          format="yyyy年MM月"
          value-format="yyyy/MM"
          placeholder="选择月份"
          @change="changeTab(1)"
        >
        </el-date-picker> -->
        <el-date-picker
          v-show="tabIndex == 1"
          v-model="dataTime"
          type="monthrange"
          range-separator="-"
          :clearable="false"
          format="yyyy/MM"
          value-format="yyyy/MM"
          start-placeholder="开始月份"
          end-placeholder="结束月份"
          @change="changeTab(1)"
        >
        </el-date-picker>
        <el-date-picker
          v-show="tabIndex == 2"
          v-model="dataTimeArr"
          type="monthrange"
          range-separator="-"
          :clearable="false"
          format="yyyy/MM"
          value-format="yyyy/MM"
          start-placeholder="开始月份"
          end-placeholder="结束月份"
          @change="changeTab(2)"
        >
        </el-date-picker>
      </div>

      <div class="userWrap">
        <div class="imgBtn" @click="showUserFn"></div>

        <transition name="el-fade-in-linear">
          <div class="userBox" v-show="showUser">
            <div class="row">
              <div class="label">姓名</div>
              <div class="value">{{ userInfo.username || "" }}</div>
            </div>
            <div class="row">
              <div class="label">工号</div>
              <div class="value">{{ userInfo.userid || "" }}</div>
            </div>
            <div class="row">
              <div class="label">部门</div>
              <div class="value">
                {{ userInfo.office_name || "" }}
              </div>
            </div>

            <div class="row1">
              <div class="loginBtnBox" @click="changePassWordFn($event)">
                <img src="../assets/img/change.png" />
                <span>修改密码</span>
              </div>

              <div class="loginBtnBox" @click="loginOutFn($event)">
                <img src="../assets/img/out.png" />
                <span>退出登录</span>
              </div>
            </div>
          </div>
        </transition>
      </div>
    </div>

    <div class="pageContentWrap">
      <div class="contentBox">
        <div class="row">
          <div class="col col1" v-loading="arrLoading1">
            <Echarts
              class="bigEchats"
              :echartWidth="'calc(98%)'"
              :echartHeight="'calc(100%)'"
              :echartOptions="getOptionFn1"
              :echartId="'bigEchart1'"
              ref="bigEchartRef1"
              @finished="finished('bigEchartRef1', arr1, '总览')"
            ></Echarts>
          </div>
          <div class="col col2" v-loading="arrLoading2">
            <Echarts
              class="bigEchats"
              :echartWidth="'calc(98%)'"
              :echartHeight="'calc(100%)'"
              :echartOptions="getOptionFn2"
              :echartId="'bigEchart2'"
              ref="bigEchartRef2"
              @finished="
                finished('bigEchartRef2', arr2, '贷款业务全流程风险监测模型')
              "
            ></Echarts>
          </div>
          <div class="col col3" v-loading="arrLoading3">
            <Echarts
              class="bigEchats"
              :echartWidth="'calc(98%)'"
              :echartHeight="'calc(100%)'"
              :echartOptions="getOptionFn3"
              :echartId="'bigEchart3'"
              ref="bigEchartRef3"
              @finished="
                finished('bigEchartRef3', arr3, '存款业务风险监测模型')
              "
            ></Echarts>
          </div>
        </div>
        <div class="row">
          <div class="col col4" v-loading="arrLoading4">
            <Echarts
              class="bigEchats"
              :echartWidth="'calc(98%)'"
              :echartHeight="'calc(100%)'"
              :echartOptions="getOptionFn4"
              :echartId="'bigEchart4'"
              ref="bigEchartRef4"
              @finished="
                finished('bigEchartRef4', arr4, '资产质量风险监测模型')
              "
            ></Echarts>
          </div>
          <div class="col col5" v-loading="arrLoading5">
            <Echarts
              class="bigEchats"
              :echartWidth="'calc(98%)'"
              :echartHeight="'calc(100%)'"
              :echartOptions="getOptionFn5"
              :echartId="'bigEchart5'"
              ref="bigEchartRef5"
              @finished="
                finished('bigEchartRef5', arr5, '合规与操作风险监测模型')
              "
            ></Echarts>
          </div>
          <div class="col col6" v-loading="arrLoading6">
            <Echarts
              class="bigEchats"
              :echartWidth="'calc(98%)'"
              :echartHeight="'calc(100%)'"
              :echartOptions="getOptionFn6"
              :echartId="'bigEchart6'"
              ref="bigEchartRef6"
              @finished="
                finished(
                  'bigEchartRef6',
                  arr6,
                  '区域与行业专项风险（场景化类）'
                )
              "
            ></Echarts>
          </div>
        </div>
        <div class="row row1" v-loading="tableLoading">
          <div class="tableWrap">
            <el-table :data="tableData" height="100%" style="width: 100%">
              <el-table-column label="排名" width="80" align="center">
                <template slot-scope="scope">
                  <div class="indexBox">
                    <span>{{
                      (pageNum - 1) * pageSize + scope.$index + 1
                    }}</span>
                  </div>
                </template>
              </el-table-column>
              <el-table-column prop="机构名称" label="机构名称" min-width="200">
                <template slot-scope="scope">
                  <div class="nameText">
                    <span>{{ scope.row["机构名称"] }}</span>
                  </div>
                </template>
              </el-table-column>
              <el-table-column
                prop="机构编码"
                label="机构编码"
                min-width="130"
              ></el-table-column>
              <el-table-column
                prop="模型类型1记录数"
                label="贷款业务全流程风险监测模型(个)"
                min-width="200"
                align="center"
              >
                <template slot-scope="scope">
                  <div
                    class="clickText"
                    v-if="scope.row['模型类型1记录数'] > 0"
                    @click="
                      downDetail(1, scope.row, '贷款业务全流程风险监测模型')
                    "
                  >
                    <span>{{ scope.row["模型类型1记录数"] }}</span>
                  </div>
                  <span v-else>{{ scope.row["模型类型1记录数"] }}</span>
                </template>
              </el-table-column>
              <el-table-column
                prop="模型类型2记录数"
                label="存款业务风险监测模型(个)"
                min-width="170"
                align="center"
              >
                <template slot-scope="scope">
                  <div
                    class="clickText"
                    v-if="scope.row['模型类型2记录数'] > 0"
                    @click="downDetail(2, scope.row, '存款业务风险监测模型')"
                  >
                    <span>{{ scope.row["模型类型2记录数"] }}</span>
                  </div>
                  <span v-else>{{ scope.row["模型类型2记录数"] }}</span>
                </template>
              </el-table-column>
              <el-table-column
                prop="模型类型3记录数"
                label="资产质量风险监测模型(个)"
                min-width="180"
                align="center"
              >
                <template slot-scope="scope">
                  <div
                    class="clickText"
                    v-if="scope.row['模型类型3记录数'] > 0"
                    @click="downDetail(3, scope.row, '资产质量风险监测模型')"
                  >
                    <span>{{ scope.row["模型类型3记录数"] }}</span>
                  </div>
                  <span v-else>{{ scope.row["模型类型3记录数"] }}</span>
                </template>
              </el-table-column>
              <el-table-column
                prop="模型类型4记录数"
                label="合规与操作风险监测模型(个)"
                min-width="180"
                align="center"
              >
                <template slot-scope="scope">
                  <div
                    class="clickText"
                    v-if="scope.row['模型类型4记录数'] > 0"
                    @click="downDetail(4, scope.row, '合规与操作风险监测模型')"
                  >
                    <span>{{ scope.row["模型类型4记录数"] }}</span>
                  </div>
                  <span v-else>{{ scope.row["模型类型4记录数"] }}</span>
                </template>
              </el-table-column>
              <el-table-column
                prop="模型类型5记录数"
                label="区域与行业专项风险(场景化类)(个)"
                min-width="220"
                align="center"
              >
                <template slot-scope="scope">
                  <div
                    class="clickText"
                    v-if="scope.row['模型类型5记录数'] > 0"
                    @click="
                      downDetail(5, scope.row, '区域与行业专项风险(场景化类)')
                    "
                  >
                    <span>{{ scope.row["模型类型5记录数"] }}</span>
                  </div>
                  <span v-else>{{ scope.row["模型类型5记录数"] }}</span>
                </template>
              </el-table-column>
            </el-table>
          </div>
        </div>
      </div>
    </div>

    <!-- 下钻弹窗 -->
    <el-dialog
      :visible.sync="dialogVisible"
      width="100%"
      top="11vh"
      class="dialogClass"
      :modal-append-to-body="false"
      :close-on-click-modal="false"
      @close="dialogClose"
    >
      <div class="dialogWrap">
        <div class="dialogName">{{ dialogName }}</div>
        <Echarts
          v-loading="downDetailLoading"
          class="bigEchats"
          :echartWidth="'calc(94%)'"
          :echartHeight="'calc(94%)'"
          :echartOptions="getDialogOption"
          :echartId="'dialogEchart'"
          ref="dialogEchart"
          @finished="finished('dialogEchart', [], '', dialogName != '总览')"
        ></Echarts>
      </div>
    </el-dialog>

    <!-- 详情弹窗 -->
    <el-dialog
      :visible.sync="dialogShow"
      width="100%"
      top="11vh"
      class="dialogClass"
      :modal-append-to-body="false"
      :close-on-click-modal="false"
      @close="dialogClose1"
    >
      <div class="dialogWrap">
        <div class="dialogName">{{ dialogName1 }}</div>

        <div class="detailWrap" v-loading="dialogLoading1">
          <div class="seekBox">
            <el-form :inline="true" :model="seekForm">
              <el-form-item label="机构：">
                <el-select
                  v-model="seekForm.orgId"
                  placeholder="选择机构"
                  filterable
                  clearable
                  @change="getDetailFn"
                >
                  <el-option
                    v-for="item in orgList"
                    :key="item.jgbm + 'jj'"
                    :label="item.jgmc"
                    :value="item.jgbm"
                  >
                  </el-option>
                </el-select>
              </el-form-item>
              <el-form-item label="日期：">
                <el-date-picker
                  v-model="seekForm.time"
                  type="monthrange"
                  range-separator="-"
                  :clearable="false"
                  format="yyyy/MM"
                  value-format="yyyy/MM"
                  start-placeholder="开始月份"
                  end-placeholder="结束月份"
                  @change="getDetailFn"
                >
                </el-date-picker>

                <!-- <el-date-picker
                  v-model="seekForm.time"
                  type="month"
                  format="yyyy-MM"
                  value-format="yyyy-MM"
                  :clearable="false"
                  placeholder="选择日期"
                  @change="getDetailFn"
                >
                </el-date-picker> -->
              </el-form-item>
              <el-form-item label="模型：">
                <el-select
                  v-model="seekForm.modelName"
                  placeholder="选择模型"
                  filterable
                  @change="changeModel"
                >
                  <el-option
                    v-for="item in modelList"
                    :key="item.model_name + 'gg'"
                    :label="item.model_name"
                    :value="item.model_name"
                  >
                  </el-option>
                </el-select>
              </el-form-item>
            </el-form>

            <!-- <div
              class="downBtn"
              @click="getExportFn()"
              v-loading="exportLoading"
            >
              导出
            </div> -->
          </div>
          <div class="tableBox">
            <el-table
              :data="detailArr"
              height="calc(100% - 60px)"
              style="width: 100%"
            >
              <el-table-column
                :prop="`KPI_VAL${index}`"
                :label="item"
                min-width="100"
                v-for="(item, index) in detailHeader"
                :key="index + 'sd'"
              ></el-table-column>
            </el-table>
            <el-pagination
              @size-change="sizeChange"
              @current-change="currentChange"
              :current-page="pageNum"
              :page-sizes="[20, 50, 100, 200]"
              :page-size="pageSize"
              layout="total, sizes, prev, pager, next, jumper"
              :total="total"
            >
            </el-pagination>
          </div>
        </div>
      </div>
    </el-dialog>

    <!-- 模型配置 -->
    <el-dialog
      :visible.sync="modelDialog"
      width="100%"
      top="11vh"
      class="dialogClass"
      :modal-append-to-body="false"
      :close-on-click-modal="false"
      @close="dialogClose1"
    >
      <div class="dialogWrap">
        <div class="dialogName">模型配置</div>

        <div class="detailWrap">
          <div class="seekBox">
            <el-form
              :inline="true"
              :model="seekForm1"
              :rules="rules"
              ref="modelConfig"
            >
              <el-form-item label="模型：">
                <el-select
                  v-model="seekForm1.modelName"
                  placeholder="选择模型"
                  filterable
                  @change="getModelConfigFn"
                >
                  <el-option
                    v-for="item in modelList"
                    :key="item.model_name + '13'"
                    :label="item.model_name"
                    :value="item.model_name"
                  >
                  </el-option>
                </el-select>
              </el-form-item>

              <el-form-item label="模型类别（必选）：" prop="modelType">
                <el-select
                  v-model="seekForm1.modelType"
                  placeholder="选择模型"
                  filterable
                >
                  <el-option
                    v-for="item in modeTypelList"
                    :key="item.value + '66'"
                    :label="item.label"
                    :value="item.value"
                  >
                  </el-option>
                </el-select>
              </el-form-item>
            </el-form>
          </div>
          <div class="tableBox" v-loading="dialogLoading2">
            <el-table
              :data="modelTableList"
              height="calc(100% - 80px)"
              style="width: 100%"
            >
              <el-table-column prop="model_name" label="模型字段">
                <template slot-scope="scope">
                  <span>{{ scope.row.model_name }}</span>
                </template>
              </el-table-column>
              <el-table-column prop="model_name_des" label="模型字段中文">
                <template slot-scope="scope">
                  <el-input
                    v-model="scope.row.model_name_des"
                    clearable
                    placeholder="请输入模型字段中文"
                  ></el-input>
                </template>
              </el-table-column>
              <el-table-column prop="model_name_disable" label="是否展示">
                <template slot-scope="scope">
                  <el-switch
                    v-model="scope.row.model_name_disable"
                    inactive-value="0"
                    active-value="1"
                    active-color="#13ce66"
                    inactive-color="#ff4949"
                  >
                  </el-switch>
                </template>
              </el-table-column>
            </el-table>

            <div class="btnBox">
              <el-button
                type="primary"
                @click="settingConfirmFn()"
                :loading="dialogLoading2"
                >确定</el-button
              >
              <el-button @click="modelDialog = false">关闭</el-button>
            </div>
          </div>
        </div>
      </div>
    </el-dialog>

    <!-- 数据管理 -->
    <el-dialog
      :visible.sync="batchDialog"
      width="100%"
      top="11vh"
      class="dialogClass"
      :modal-append-to-body="false"
      :close-on-click-modal="false"
      @close="dialogClose1"
    >
      <div class="dialogWrap">
        <div class="dialogName">数据管理</div>

        <div class="detailWrap">
          <div class="seekBox">
            <el-form :inline="true" :model="seekForm2" ref="dataConfig">
              <el-form-item label="模型名称：">
                <el-select
                  v-model="seekForm2.model_name"
                  placeholder="选择模型"
                  filterable
                  clearable
                  @change="batchFn()"
                >
                  <el-option
                    v-for="item in modelAllList"
                    :key="item.model_name + 'cc'"
                    :label="item.model_name"
                    :value="item.model_name"
                  >
                  </el-option>
                </el-select>
              </el-form-item>

              <el-form-item label="机构名称：">
                <el-select
                  v-model="seekForm2.jgbm"
                  placeholder="选择模型"
                  filterable
                  clearable
                  @change="batchFn()"
                >
                  <el-option
                    v-for="item in orgAllList"
                    :key="item.jgbm + item.jgmc + 'dd'"
                    :label="item.jgmc"
                    :value="item.jgbm"
                  >
                  </el-option>
                </el-select>
              </el-form-item>

              <el-button
                style="float: right; margin-right: 30px"
                :loading="removeMoreLoading"
                :disabled="multipleSelection.length == 0"
                type="danger"
                @click="removeBatchFn()"
                >批量删除</el-button
              >
            </el-form>
          </div>
          <div class="tableBox" height="100%" v-loading="batchLoading">
            <el-table
              :data="batchList"
              height="100%"
              style="width: 100%"
              @selection-change="handleSelectionChange"
              @sort-change="sortChange"
            >
              <el-table-column type="selection" width="55"> </el-table-column>
              <el-table-column
                prop="model_name"
                label="模型名称"
                min-width="120px"
                sortable="custom"
              ></el-table-column>
              <el-table-column
                prop="jgmc"
                label="机构名称"
                min-width="120px"
                sortable="custom"
              ></el-table-column>
              <el-table-column
                prop="count"
                label="数量"
                min-width="100px"
                sortable="custom"
              ></el-table-column>
              <el-table-column
                prop="create_time"
                label="创建时间"
                min-width="140px"
                sortable="custom"
              ></el-table-column>
              <el-table-column
                prop="batch_no"
                label="文件名称"
                min-width="200px"
              ></el-table-column>
              <el-table-column label="操作" min-width="80px">
                <template slot-scope="scope">
                  <el-button
                    :loading="scope.row.removeLoading"
                    type="danger"
                    @click="removeBatchFn(scope.row)"
                    >删除</el-button
                  >
                </template>
              </el-table-column>
            </el-table>
          </div>
        </div>
      </div>
    </el-dialog>

    <!-- 部门管理 -->
    <el-dialog
      :visible.sync="orgDialog"
      width="100%"
      top="11vh"
      class="dialogClass"
      :modal-append-to-body="false"
      :close-on-click-modal="false"
      @close="dialogClose1"
    >
      <div class="dialogOrgWrap">
        <div class="dialogName">部门管理</div>

        <div class="searchBox">
          <div class="addBtn" @click="editOrgFn()">新增</div>
        </div>

        <div class="dialogOrgBox">
          <div class="listBox">
            <div class="tableBox" height="100%" v-loading="orgLoading">
              <el-table
                :data="orgDataList"
                :show-header="false"
                height="100%"
                style="width: 100%"
                @cell-click="colClickFn"
              >
                <el-table-column width="60" align="center">
                  <template slot-scope="scope">
                    <el-checkbox
                      v-model="scope.row.checked"
                      @change="changeCheckOrg(scope.row)"
                    ></el-checkbox>
                  </template>
                </el-table-column>
                <el-table-column
                  prop="office_code"
                  label="部门号"
                  min-width="80px"
                  sortable="custom"
                ></el-table-column>
                <el-table-column
                  prop="office_name"
                  label="部门名称"
                  min-width="160px"
                  sortable="custom"
                ></el-table-column>
                <el-table-column label="操作" min-width="70px">
                  <template slot-scope="scope">
                    <el-button type="text" @click="editOrgFn(scope.row)"
                      >编辑</el-button
                    >
                    <el-button
                      :loading="scope.row.removeLoading"
                      type="text"
                      style="color: #f56c6c"
                      @click="removeOrgFn(scope.row)"
                      >删除</el-button
                    >
                  </template>
                </el-table-column>
              </el-table>
            </div>
          </div>

          <div class="listBox">
            <div class="tableBox" height="100%" v-loading="allModelLoading">
              <el-table
                :data="allModelList"
                :show-header="false"
                @selection-change="selectionChange"
                height="100%"
                style="width: 100%"
                ref="orgModelRef"
              >
                <el-table-column type="selection" width="55" align="center">
                </el-table-column>
                <el-table-column
                  prop="model_name"
                  label="模型名称"
                  sortable="custom"
                ></el-table-column>
              </el-table>
            </div>
          </div>
        </div>
      </div>
    </el-dialog>

    <!-- 新增、编辑 部门 -->
    <el-dialog
      :visible.sync="editOrgDialog"
      width="450px"
      top="11vh"
      :title="orgForm.office_id ? '编辑部门' : '新增部门'"
      class="passDialogWrap"
      :modal-append-to-body="false"
      :close-on-click-modal="false"
      @close="dialogClose1"
    >
      <div class="passWrap">
        <el-form
          :model="orgForm"
          :rules="editOrgRules"
          ref="orgFormRef"
          label-width="95px"
          class="ms-content changeBox"
        >
          <el-form-item prop="office_code" label="部门编号">
            <el-input
              placeholder="请输入部门编号"
              v-model.trim="orgForm.office_code"
              oninput="value=value.replace(/[\u4E00-\u9FA5]/g,'')"
            ></el-input>
          </el-form-item>
          <el-form-item prop="office_name" label="部门名称">
            <el-input
              placeholder="请输入部门名称"
              v-model.trim="orgForm.office_name"
              maxlength="50"
            ></el-input>
          </el-form-item>
        </el-form>
      </div>
      <span slot="footer" class="dialog-footer">
        <el-button
          type="primary"
          @click="editOrgConfirmFn()"
          :loading="editOrgLoading"
          >确 定</el-button
        >
        <el-button @click="dialogClose1()">取 消</el-button>
      </span>
    </el-dialog>

    <!-- 人员管理 -->
    <el-dialog
      :visible.sync="userDialog"
      width="100%"
      top="11vh"
      class="dialogClass"
      :modal-append-to-body="false"
      :close-on-click-modal="false"
      @close="dialogClose1"
    >
      <div class="dialogOrgWrap dialogOrgWrap1">
        <div class="dialogName">人员管理</div>

        <div class="searchBox">
          <el-input
            placeholder="请输入工号/姓名"
            v-model.trim="userSearchForm.keyword"
            clearable
          ></el-input>
          <div class="addBtn" @click="searchUser()">搜索</div>
          <div class="addBtn" @click="editUserFn()">新增</div>
        </div>

        <div class="dialogOrgBox">
          <div class="listBox">
            <div class="tableBox" height="100%" v-loading="userLoading">
              <el-table :data="userDataList" height="100%" style="width: 100%">
                <el-table-column
                  prop="userid"
                  label="工号"
                  min-width="70px"
                ></el-table-column>
                <el-table-column
                  prop="username"
                  label="姓名"
                  min-width="80px"
                ></el-table-column>
                <el-table-column
                  prop="office_name"
                  label="部门名称"
                  min-width="100px"
                ></el-table-column>
                <el-table-column
                  prop="admin_flg"
                  label="是否为管理员"
                  min-width="100px"
                >
                  <template slot-scope="scope">
                    <el-switch
                      v-model="scope.row.admin_flg"
                      @change="editUserConfirmFn(scope.row)"
                      :disabled="scope.row.userid == 'admin'"
                      :active-value="1"
                      :inactive-value="0"
                      active-color="#13ce66"
                      inactive-color="#ff4949"
                    >
                    </el-switch>
                  </template>
                </el-table-column>
                <el-table-column label="操作" min-width="80px">
                  <template slot-scope="scope">
                    <el-button type="text" @click="editUserFn(scope.row)"
                      >编辑</el-button
                    >
                    <el-button
                      v-if="scope.row.userid != 'admin'"
                      :loading="scope.row.removeLoading"
                      type="text"
                      style="color: #f56c6c"
                      @click="removeUserFn(scope.row)"
                      >删除</el-button
                    >

                    <el-button type="text" :loading="scope.row.resetLoading" style="color:#67C23A" @click="resetUserFn(scope.row)"
                      >重置密码</el-button
                    >
                  </template>
                </el-table-column>
              </el-table>

              <el-pagination
                @size-change="userSizeChange"
                @current-change="userCurrentChange"
                :current-page="userPageNum"
                :page-sizes="[20, 50, 100, 200]"
                :page-size="userPageSize"
                layout="total, sizes, prev, pager, next, jumper"
                :total="userTotal"
              >
              </el-pagination>
            </div>
          </div>
        </div>
      </div>
    </el-dialog>

    <!-- 新增、编辑 人员 -->
    <el-dialog
      :visible.sync="editUserDialog"
      width="450px"
      top="11vh"
      :title="userForm.id ? '编辑人员' : '新增人员'"
      class="passDialogWrap"
      :modal-append-to-body="false"
      :close-on-click-modal="false"
      @close="dialogClose1"
    >
      <div class="passWrap">
        <el-form
          :model="userForm"
          :rules="editUserRules"
          ref="userFormRef"
          label-width="105px"
          class="ms-content changeBox"
        >
          <el-form-item prop="userid" label="工号">
            <el-input
              placeholder="请输入工号"
              v-model.trim="userForm.userid"
              oninput="value=value.replace(/[\u4E00-\u9FA5]/g,'')"
            ></el-input>
          </el-form-item>
          <el-form-item prop="username" label="姓名">
            <el-input
              placeholder="请输入姓名"
              v-model.trim="userForm.username"
              maxlength="50"
            ></el-input>
          </el-form-item>
          <el-form-item prop="office_id" label="部门">
            <el-select v-model="userForm.office_id" placeholder="请选择">
              <el-option
                v-for="item in orgDataList"
                :key="item.office_id"
                :label="item.office_name"
                :value="item.office_id"
              >
              </el-option>
            </el-select>
          </el-form-item>
          <el-form-item label="是否为管理员">
            <el-switch
              v-model="userForm.admin_flg"
              :disabled="userForm.userid == 'admin'"
              :active-value="1"
              :inactive-value="0"
              active-color="#13ce66"
              inactive-color="#ff4949"
            >
            </el-switch>
          </el-form-item>
        </el-form>
      </div>
      <span slot="footer" class="dialog-footer">
        <el-button
          type="primary"
          @click="editUserConfirmFn()"
          :loading="editUserLoading"
          >确 定</el-button
        >
        <el-button @click="dialogClose1()">取 消</el-button>
      </span>
    </el-dialog>

    <!-- 修改密码 -->
    <el-dialog
      :visible.sync="passDialog"
      width="450px"
      top="11vh"
      title="修改密码"
      class="passDialogWrap"
      :modal-append-to-body="false"
      :close-on-click-modal="false"
      @close="dialogClose1"
    >
      <div class="passWrap">
        <el-form
          :model="changeParam"
          :rules="checkRules"
          ref="checkForm"
          label-width="85px"
          class="ms-content changeBox"
        >
          <el-form-item prop="password_old" label="旧密码">
            <el-input
              show-password
              placeholder="请输入旧密码"
              v-model.trim="changeParam.password_old"
              oninput="value=value.replace(/[\u4E00-\u9FA5]/g,'')"
              maxlength="50"
              autocomplete="new-password"
            ></el-input>
          </el-form-item>
          <el-form-item prop="password" label="新密码">
            <el-input
              show-password
              placeholder="请输入新密码"
              v-model.trim="changeParam.password"
              oninput="value=value.replace(/[\u4E00-\u9FA5]/g,'')"
              maxlength="50"
              autocomplete="new-password"
            ></el-input>
          </el-form-item>
          <el-form-item prop="password_new" label="确认密码">
            <el-input
              show-password
              placeholder="请再一次输入密码"
              v-model.trim="changeParam.password_new"
              oninput="value=value.replace(/[\u4E00-\u9FA5]/g,'')"
              maxlength="50"
              @keyup.enter.native="confirmChangePass()"
            ></el-input>
          </el-form-item>
        </el-form>
      </div>
      <span slot="footer" class="dialog-footer">
        <el-button
          type="primary"
          @click="confirmChangePass()"
          :loading="checkLoading"
          >确 定</el-button
        >
        <el-button @click="dialogClose1()">取 消</el-button>
      </span>
    </el-dialog>
  </div>
</template>

<script>
import { chunk } from "lodash";

import { mapState } from "vuex";

import {
  getChartData,
  getOrgTypeStats,
  getOrgTypeStats2,
  getChartDataMonthly,
  getDetail,
  getModelList,
  getOrgList,
  getDataAll,
  getDataMonthlyAll,
  getExport,
  getModelConfig,
  getModelConfigUpd,
  getBatchStats,
  getBatchDelete,
  getImport,
  getChangePassWord,
  getOfficeList,
  getAllModelList,
  getEditOffice,
  getAddOffice,
  getDelOffice,
  setModelOffice,
  getUserList,
  getAddUser,
  getEditUser,
  getDelUser,
  getRest
} from "@/api/home";

import Echarts from "@/components/echarts.vue";

let timer = null;

export default {
  name: "HomeView",
  data() {
    var validateOldPass = (rule, value, callback) => {
      if (value === "") {
        callback(new Error("请输入密码"));
      } else if (value.replace(/' '/g, "").length < 6) {
        callback(new Error("密码最小长度为6位"));
      } else {
        callback();
      }
    };
    var validatePass = (rule, value, callback) => {
      if (value === "") {
        callback(new Error("请输入密码"));
      } else if (value.replace(/' '/g, "").length < 6) {
        callback(new Error("密码最小长度为6位"));
      } else {
        if (this.changeParam.password !== "") {
          this.$refs.checkForm.validateField("password_new");
        }
        callback();
      }
    };
    var validatePass2 = (rule, value, callback) => {
      if (value === "") {
        callback(new Error("请再次输入密码"));
      } else if (value !== this.changeParam.password) {
        callback(new Error("两次输入密码不一致!"));
      } else {
        callback();
      }
    };
    return {
      seekForm2: {},
      multipleSelection: [],
      removeMoreLoading: false,
      modelAllList: [],
      orgAllList: [],

      dateStr: "",
      dateWeek: "",
      dateTime: "",

      tabIndex: 1,

      dataTime: [],
      dataTimeArr: [],

      arr1: [],
      arr2: [],
      arr3: [],
      arr4: [],
      arr5: [],
      arr6: [],
      dialogArr: [],
      dialogName: "",
      arrLoading1: false,
      arrLoading2: false,
      arrLoading3: false,
      arrLoading4: false,
      arrLoading5: false,
      arrLoading6: false,
      tableLoading: false,

      dialogVisible: false,
      dialogLoading: false,

      tableData: [],

      dialogShow: false,
      dialogLoading1: false,
      dialogName1: "",
      detailHeader: [],
      detailArr: [],
      total: 0,
      pageNum: 1,
      pageSize: 20,

      seekForm: {},
      modelList: [],
      orgList: [],
      exportLoading: false,
      uploadLoading: false,

      downDetailLoading: false,
      downDetailParams: {},
      modelDialog: false,
      seekForm1: {},
      dialogLoading2: false,
      modelTableObj: {},
      modelTableList: [],

      batchDialog: false,
      batchLoading: false,
      batchList: [],

      modeTypelList: [
        {
          label: "贷款业务全流程风险监测模型",
          value: "1",
        },
        {
          label: "存款业务风险监测模型",
          value: "2",
        },
        {
          label: "资产质量风险监测模型",
          value: "3",
        },
        {
          label: "合规与操作风险监测模型",
          value: "4",
        },
        {
          label: "区域与行业专项风险（场景化类）",
          value: "5",
        },
      ],
      rules: {
        modelType: [
          { required: true, message: "请选择模型类别", trigger: "change" },
        ],
      },
      fileList: [],

      showSetting: false,
      showUser: false,

      orgDialog: false,
      orgLoading: false,
      orgDataList: [],

      allModelList: [],
      selectArr: [],
      allModelLoading: false,
      checkRow: {},
      oldSelectArr: [],

      passDialog: false,
      checkLoading: false,
      changeParam: {
        password_old: "",
        password: "",
        password_new: "",
      },

      checkRules: {
        password_old: [
          {
            required: true,
            validator: validateOldPass,
            trigger: "blur",
          },
        ],
        password: [
          {
            required: true,
            validator: validatePass,
            trigger: "blur",
          },
        ],
        password_new: [
          {
            required: true,
            validator: validatePass2,
            trigger: "blur",
          },
        ],
      },

      editOrgDialog: false,
      editOrgLoading: false,
      orgForm: {
        office_code: "",
        office_name: "",
      },
      editOrgRules: {
        office_code: [
          { required: true, message: "请输入部门号", trigger: "blur" },
        ],
        office_name: [
          { required: true, message: "请输入部门名称", trigger: "blur" },
        ],
      },

      userDialog: false,
      userLoading: false,
      userDataList: [],
      userTotal: 0,
      userPageNum: 1,
      userPageSize: 20,

      editUserDialog: false,
      editUserLoading: false,
      userForm: {
        office_code: "",
        office_name: "",
      },
      userSearchForm: {},
      editUserRules: {
        username: [{ required: true, message: "请输入姓名", trigger: "blur" }],
        userid: [{ required: true, message: "请输入工号", trigger: "blur" }],
        office_id: [
          { required: true, message: "请选择部门", trigger: "change" },
        ],
      },
    };
  },
  computed: {
    ...mapState({
      userInfo: (state) => state.User.userInfo,
      showImport: (state) => state.User.userInfo.admin_flg == "1",
    }),
    getDialogOption() {
      if (this.tabIndex == "1") {
        return this.getBarOptions(this.dialogArr, this.dialogIndex, true);
      } else {
        return this.getLineOptions(this.dialogArr, true);
      }
    },
    getOptionFn1() {
      if (this.tabIndex == "1") {
        return this.getPieOptions(this.arr1);
      } else {
        return this.getLineOptions(this.arr1);
      }
    },
    getOptionFn2() {
      if (this.tabIndex == "1") {
        return this.getBarOptions(this.arr2, "2");
      } else {
        return this.getLineOptions(this.arr2);
      }
    },
    getOptionFn3() {
      if (this.tabIndex == "1") {
        return this.getBarOptions(this.arr3, "3");
      } else {
        return this.getLineOptions(this.arr3);
      }
    },
    getOptionFn4() {
      if (this.tabIndex == "1") {
        return this.getBarOptions(this.arr4, "4");
      } else {
        return this.getLineOptions(this.arr4);
      }
    },
    getOptionFn5() {
      if (this.tabIndex == "1") {
        return this.getBarOptions(this.arr5, "5");
      } else {
        return this.getLineOptions(this.arr5);
      }
    },
    getOptionFn6() {
      if (this.tabIndex == "1") {
        return this.getBarOptions(this.arr6, "6");
      } else {
        return this.getLineOptions(this.arr6);
      }
    },
    getDetailParams() {
      return {
        modelName: this.dialogName1,
        // month: (this.seekForm.time || "").replace("-", ""),
        ...this.getParams(this.seekForm.time || []),
        jgbm: this.seekForm.orgId || "",
        page: this.pageNum,
        per_page: this.pageSize,
      };
    },
  },
  watch: {
    showSetting(val) {
      if (val) {
        document.body.addEventListener("click", this.handleBodyClick);
      } else {
        document.body.removeEventListener("click", this.handleBodyClick);
      }
    },
    showUser(val) {
      if (val) {
        document.body.addEventListener("click", this.handleBodyClick);
      } else {
        document.body.removeEventListener("click", this.handleBodyClick);
      }
    },
    checkRow(val, oldVal) {
      if (
        JSON.stringify(val) != JSON.stringify(oldVal) &&
        JSON.stringify(oldVal) != "{}"
      ) {
        if (
          JSON.stringify(oldVal.model_names) !=
          JSON.stringify(this.oldSelectArr)
        ) {
          this.setModelOfficeFn(oldVal);
        }
      }
    },
  },
  components: {
    Echarts,
  },
  created() {
    this.getDateTimeFn(true);
    setInterval(() => {
      this.getDateTimeFn();
    }, 1000);

    this.changeTab(1);
  },
  methods: {
    searchUser() {
      this.userTotal = 0;
      this.userPageNum = 1;
      this.userPageSize = 20;
      this.getUserListFn();
    },
    userCurrentChange(val) {
      this.userPageNum = val;
      this.getUserListFn();
    },

    userSizeChange(val) {
      this.userPageSize = val;
      this.getUserListFn();
    },
    editUserFn(row) {
      this.userForm = row ? JSON.parse(JSON.stringify(row)) : { admin_flg: 0};
      this.editUserDialog = true;
    },
    removeUserFn(row){
      this.$confirm("是否确定删除该人员?", "提示", {
        confirmButtonText: "确定",
        cancelButtonText: "取消",
        type: "warning",
      })
        .then(async () => {
          row.removeLoading = true;

          let res = await getDelUser(row.id);

          this.$message.success("删除成功!");
          this.searchUser();

          row.removeLoading = false;
        })
        .catch(() => {});
    },

    resetUserFn(row){
       this.$confirm("是否确定重置该人员密码?", "提示", {
        confirmButtonText: "确定",
        cancelButtonText: "取消",
        type: "warning",
      })
        .then(async () => {
          row.resetLoading = true;

          let res = await getRest(row.id);

          this.$message.success("重置成功!");
          if (row.id == this.userInfo.id){
            this.$store.commit("User/USER_INFO", {});
            localStorage.removeItem("vuex");

            this.$router.push("/login");
          }

          row.resetLoading = false;
        })
        .catch(() => {});
    },

    editUserConfirmFn(row) {
      if (row){
        this.editDataFn(row)
        return
      }
      this.$refs.userFormRef.validate(async (valid) => {
        if (valid) {
          this.editDataFn()
        }
      });
    },

    async editDataFn(row){
      let editData = row || this.userForm
      this.editUserLoading = true;
      let res = {};
      if (editData.id) {
        res = await getEditUser(editData);
      } else {
        res = await getAddUser(editData);
      }
      this.$message.success(
        editData.id ? "编辑人员成功!" : "新增人员成功!"
      );

      this.editUserDialog = false;
      this.$refs.userFormRef && this.$refs.userFormRef.resetFields();
      if (!row){
        this.searchUser();
      }

      this.editUserLoading = false;
    },

    async getUserListFn() {
      this.userLoading = true;
      let res = await getUserList({ keyword: this.userSearchForm.keyword });

      if (res.items instanceof Array) {
        this.userDataList = res.items.map(obj=>{
          return {
            ...obj,
            resetLoading: false,
            removeLoading: false
          }
        });
        this.userTotal = res.total || 0;
      }

      this.userLoading = false;
    },

    async setModelOfficeFn(oldVal) {
      let res = await setModelOffice({
        office_id: oldVal.office_id,
        model_names: this.oldSelectArr,
      });

      this.$message.success("修改部门关联模型成功!");

      this.getOfficeListFn();
    },
    async getAllModelListFn() {
      this.allModelLoading = true;
      let res = await getAllModelList();

      if (res instanceof Array) {
        this.allModelList = res;
      }

      this.allModelLoading = false;
    },

    colClickFn(row, column, cell, event) {
      if (["office_code", "office_name"].includes(column.property)) {
        let firstFlag = JSON.stringify(this.checkRow) != "{}";
        if (firstFlag) {
          this.oldSelectArr = JSON.parse(JSON.stringify(this.selectArr));
        }
        this.checkRow = row;

        this.orgDataList = this.orgDataList.map((obj) => {
          return {
            ...obj,
            checked: row.office_id == obj.office_id,
          };
        });
        this.$refs.orgModelRef && this.$refs.orgModelRef.clearSelection();
        this.selectArr = row.model_names || [];
        if (!firstFlag) {
          this.oldSelectArr = JSON.parse(JSON.stringify(this.selectArr));
        }
        this.selectTable();
      }
    },

    selectTable() {
      if (this.$refs.orgModelRef) {
        this.selectArr.forEach((item) => {
          this.$refs.orgModelRef.toggleRowSelection(
            this.allModelList.find((obj) => obj.model_name == item),
            true
          );
        });
      }
    },

    async getOfficeListFn() {
      this.oldSelectArr = JSON.parse(JSON.stringify(this.selectArr));
      this.checkRow = {};
      this.$refs.orgModelRef && this.$refs.orgModelRef.clearSelection();
      this.selectArr = [];
      this.selectTable();
      this.orgLoading = true;
      let res = await getOfficeList();
      if (res instanceof Array) {
        this.orgDataList = res.map((obj) => {
          return {
            ...obj,
            checked: false,
            removeLoading: false,
          };
        });
      }

      this.orgLoading = false;
    },
    async editOrgConfirmFn() {
      this.$refs.orgFormRef.validate(async (valid) => {
        if (valid) {
          this.editOrgLoading = true;
          let res = {};
          if (this.orgForm.office_id) {
            res = await getEditOffice(this.orgForm);
          } else {
            res = await getAddOffice(this.orgForm);
          }
          this.$message.success(
            this.orgForm.office_id ? "编辑部门成功!" : "新增部门成功!"
          );

          this.editOrgDialog = false;
          this.$refs.orgFormRef && this.$refs.orgFormRef.resetFields();
          this.getOfficeListFn();

          this.editOrgLoading = false;
        }
      });
    },
    editOrgFn(row) {
      this.orgForm = row ? JSON.parse(JSON.stringify(row)) : {};
      this.editOrgDialog = true;
    },
    removeOrgFn(row) {
      this.$confirm("是否确定删除该部门?", "提示", {
        confirmButtonText: "确定",
        cancelButtonText: "取消",
        type: "warning",
      })
        .then(async () => {
          row.removeLoading = true;

          let res = await getDelOffice(row.office_id);

          this.$message.success("删除成功!");
          this.getOfficeListFn();

          row.removeLoading = false;
        })
        .catch(() => {});
    },
    selectionChange(arr) {
      this.selectArr = arr.map((obj) => obj.model_name);
    },
    changeCheckOrg(row) {
