    getPieOptions(dataArray) {
      let centerArr = ["15%", "50%"];
      let itemGap = 10;

      if (window.screen.width >= 1910) {
        centerArr = ["24%", "50%"];
        itemGap = 20;
      }

      let dataArr = (
        dataArray instanceof Array && dataArray ? dataArray : []
      ).map((obj) => {
        return {
          name: obj.typeDes,
          value: obj.count,
        };
      });
      let option = {
        tooltip: {
          trigger: "item",
        },
        legend: {
          top: "center",
          right: "0%",
          itemGap: itemGap,
          orient: "vertical",
          textStyle: {
            color: "#ffffff",
          },
          // 使用 formatter 来自定义图例内容
          formatter: function (name) {
            var total = 0;
            var targetData;
            // 遍历所有系列数据以计算总数
            option.series.forEach(function (series) {
              if (series.type === "pie") {
                series.data.forEach(function (data) {
                  if (data.name === name) {
                    targetData = data;
                  }
                  total += data.value || 0;
                });
              }
            });
            var percent =
              total == 0
                ? "0%"
                : ((targetData.value / total) * 100).toFixed(2) + "%";
            return name + "   " + targetData.value + "（" + percent + "）";
          },
        },
        series: [
          {
            type: "pie",
            radius: ["40%", "60%"],
            center: centerArr,
            avoidLabelOverlap: false,
            padAngle: 5,
            itemStyle: {
              borderRadius: 4,
            },
            label: {
              show: false,
              position: "center",
            },
            labelLine: {
              show: false,
            },
            data: dataArr,
          },
        ],
      };

      return option;
    },

    getBarOptions(dataArray, indexCode, flag) {
      let colorRgbStr = "27, 126, 242";
      if (indexCode == "2") {
        colorRgbStr = "27, 126, 242";
      } else if (indexCode == "3") {
        colorRgbStr = "255, 184, 0";
      } else if (indexCode == "4") {
        colorRgbStr = "0, 221, 181";
      } else if (indexCode == "5") {
        colorRgbStr = "255, 0, 92";
      } else if (indexCode == "6") {
        colorRgbStr = "123, 101, 255";
      }
      const VALUE = (
        dataArray instanceof Array && dataArray ? dataArray : []
      ).map((one) => one.count);
      const NAMES = (
        dataArray instanceof Array && dataArray ? dataArray : []
      ).map((one) => one.model_name);

      // 绘制左侧面
      const CubeLeft = this.$echarts.graphic.extendShape({
        shape: {
          x: 0,
          y: 0,
        },
        buildPath: function (ctx, shape) {
          const xAxisPoint = shape.xAxisPoint;
          const c0 = [shape.x + 2, shape.y];
          const c1 = [shape.x - 7, shape.y - 1];
          const c2 = [xAxisPoint[0] - 7, xAxisPoint[1] - 3];
          const c3 = [xAxisPoint[0] + 2, xAxisPoint[1]];
          ctx
            .moveTo(c0[0], c0[1])
            .lineTo(c1[0], c1[1])
            .lineTo(c2[0], c2[1])
            .lineTo(c3[0], c3[1])
            .closePath();
        },
      });
      // 绘制右侧面
      const CubeRight = this.$echarts.graphic.extendShape({
        shape: {
          x: 0,
          y: 0,
        },
        buildPath: function (ctx, shape) {
          const xAxisPoint = shape.xAxisPoint;
          const c1 = [shape.x + 2, shape.y];
          const c2 = [xAxisPoint[0] + 2, xAxisPoint[1]];
          const c3 = [xAxisPoint[0] + 10, xAxisPoint[1] - 5];
          const c4 = [shape.x + 10, shape.y - 5];
          ctx
            .moveTo(c1[0], c1[1])
            .lineTo(c2[0], c2[1])
            .lineTo(c3[0], c3[1])
            .lineTo(c4[0], c4[1])
            .closePath();
        },
      });
      // 绘制顶面
      const CubeTop = this.$echarts.graphic.extendShape({
        shape: {
          x: 0,
          y: 0,
        },
        buildPath: function (ctx, shape) {
          const c1 = [shape.x + 2, shape.y + 3];
          const c2 = [shape.x + 10, shape.y - 5]; //右点
          const c3 = [shape.x - 0, shape.y - 7];
          const c4 = [shape.x - 7, shape.y - 1];
          ctx
            .moveTo(c1[0], c1[1])
            .lineTo(c2[0], c2[1])
            .lineTo(c3[0], c3[1])
            .lineTo(c4[0], c4[1])
            .closePath();
        },
      });
      // 注册三个面图形
      this.$echarts.graphic.registerShape("CubeLeft", CubeLeft);
      this.$echarts.graphic.registerShape("CubeRight", CubeRight);
      this.$echarts.graphic.registerShape("CubeTop", CubeTop);

      let endStr = 100;
      if (flag) {
        endStr = 100;
      }

      return {
        backgroundColor: "transparent",
        dataZoom: [
          {
            type: "inside",
            throttle: "80",
            minValyeSpan: 5,
            start: 0,
            end: endStr,
            zoomLock: false,
          },
        ],
        tooltip: {
          trigger: "axis",
          axisPointer: {
            type: "shadow",
          },
          formatter: function (params) {
            const item = params[0];
            return item.name + " : " + item.value;
          },
        },
        grid: {
          left: 20,
          top: 15,
          bottom: 15,
          right: 20,
          containLabel: true,
        },
        xAxis: {
          offset: 6,
          type: "category",
          data: NAMES,
          axisLabel: {
            color: "#ffffff",
            margin: 15,
          },
          splitLine: {
            lineStyle: {
              color: "rgba(255,255,255,0.2)",
            },
          },
          axisLine: {
            show: true,
            lineStyle: {
              color: "rgba(255,255,255,0.2)",
            },
          },
          axisTick: {
            show: false,
          },
          axisLabel: {
            rotate: 0,
            color: "#FFF",
            fontSize: 14,
            formatter: (label) => {
              let text = chunk(((label || "").substr(0, 18) || "").split(""), 6)
                .map((one) => one.join(""))
                .join("\n");
              return text;
            },
          },
        },
        yAxis: [
          {
            type: "value",
            axisLine: {
              show: false,
              lineStyle: {
                color: "#7ebaf2",
              },
            },
            splitLine: {
              lineStyle: {
                color: "rgba(255,255,255,0.2)",
              },
            },
            axisTick: {
              show: false,
            },
            splitNumber: 4,
            axisLabel: {
              fontSize: 14,
              color: "#FFF",
              margin: 15,
            },
          },
        ],
        series: [
          {
            type: "custom",
            renderItem: (params, api) => {
              let cubeLeftStyle = "";
              let cubeRightStyle = "";
              let cubeTopStyle = "";
              // 颜色
              cubeLeftStyle = new this.$echarts.graphic.LinearGradient(
                0,
                0,
                0,
                1,
                [
                  {
                    offset: 0,
                    color: `rgba(${colorRgbStr}, 0.8)`,
                  },
                  {
                    offset: 0.5,
                    color: `rgba(${colorRgbStr}, 0.6)`,
                  },
                  {
                    offset: 0.8,
                    color: `rgba(${colorRgbStr}, 0.3)`,
                  },
                  {
                    offset: 1,
                    color: `rgba(${colorRgbStr}, 0.1)`,
                  },
                ]
              );
              cubeRightStyle = new this.$echarts.graphic.LinearGradient(
                0,
                0,
                0,
                1,
                [
                  {
                    offset: 0,
                    color: `rgba(${colorRgbStr}, 0.8)`,
                  },
                  {
                    offset: 0.5,
                    color: `rgba(${colorRgbStr}, 0.6)`,
                  },
                  {
                    offset: 0.8,
                    color: `rgba(${colorRgbStr}, 0.3)`,
                  },
                  {
                    offset: 1,
                    color: `rgba(${colorRgbStr}, 0.1)`,
                  },
                ]
              );
              cubeTopStyle = new this.$echarts.graphic.LinearGradient(
                0,
                0,
                0,
                1,
                [
                  {
                    offset: 0,
                    color: `rgba(${colorRgbStr}, 1)`,
                  },
                  {
                    offset: 1,
                    color: `rgba(${colorRgbStr}, 1)`,
                  },
                ]
              );
              //颜色end
              const location = api.coord([api.value(0), api.value(1)]);
              return {
                type: "group",
                children: [
                  {
                    type: "CubeLeft",
                    shape: {
                      api,
                      xValue: api.value(0),
                      yValue: api.value(1),
                      x: location[0],
                      y: location[1],
                      xAxisPoint: api.coord([api.value(0), 0]),
                    },
                    style: {
                      fill: cubeLeftStyle,
                    },
                  },
                  {
                    type: "CubeRight",
                    shape: {
                      api,
                      xValue: api.value(0),
                      yValue: api.value(1),
                      x: location[0],
                      y: location[1],
                      xAxisPoint: api.coord([api.value(0), 0]),
                    },
                    style: {
                      fill: cubeRightStyle,
                    },
                  },
                  {
                    type: "CubeTop",
                    shape: {
                      api,
                      xValue: api.value(0),
                      yValue: api.value(1),
                      x: location[0],
                      y: location[1],
                      xAxisPoint: api.coord([api.value(0), 0]),
                    },
                    style: {
                      fill: cubeTopStyle,
                    },
                  },
                ],
              };
            },
            data: VALUE,
          },
        ],
      };
    },

    getLineOptions(dataArray, flag) {
      let nameArr = [],
        dataArr = [],
        dateArr = [];

      if (dataArray.length > 0 && dataArray[0].data) {
        nameArr = dataArray[0].data.map((obj) => obj.typeDes || obj.model_name);
        dateArr = (
          dataArray instanceof Array && dataArray ? dataArray : []
        ).map((obj) => obj.month);

        nameArr.forEach((item, index) => {
          dataArr[index] = {
            name: item,
            type: "line",
            data: [],
          };
          dataArr[index].data = (
            dataArray instanceof Array && dataArray ? dataArray : []
          ).map((obj) => {
            return obj.data[index].count;
          });
        });
      }

      let legendType = "plain";
      let endStr = 100;
      if (!flag) {
        legendType = "scroll";
        endStr = 100;
      }

      return {
        animationDuration: 0,
        dataZoom: [
          {
            type: "inside",
            throttle: "80",
            minValyeSpan: 5,
            start: 0,
            end: endStr,
            zoomLock: false,
          },
        ],
        tooltip: {
          trigger: "axis",
          confine: true,
          extraCssText: "max - width: none; overflow: visible;",
        },
        legend: {
          orient: "horizontal",
          type: legendType,
          top: "0%",
          data: nameArr,
          textStyle: {
            color: "#fff",
          },
          pageTextStyle: {
            color: "#fff",
          },
          pageIconColor: "#666666",
          pageIconInactiveColor: "#fff",
        },
        grid: {
          top: "20%",
          left: "3%",
          right: "8%",
          bottom: "5%",
          containLabel: true,
        },
        xAxis: {
          type: "category",
          boundaryGap: false,
          data: dateArr,
          axisLabel: {
            color: "#ffffff",
            fintSize: 14,
            margin: 15,
          },
          axisLine: {
            lineStyle: {
              color: "rgba(255,255,255,0.2)",
            },
          },
          splitLine: {
            lineStyle: {
              color: "rgba(255,255,255,0.2)",
            },
          },
        },
        yAxis: {
          type: "value",
          nameGap: 10,
          axisLabel: {
            color: "#ffffff",
            margin: 15,
            fintSize: 14,
          },
          splitLine: {
            lineStyle: {
              color: "rgba(255,255,255,0.2)",
            },
          },
        },
        series: dataArr,
      };
    },
  },
};
</script>


